+            index: i,
+            key: 'attach-00$i',
+            fromCurrentMessage: true,
+          )
+      else
+        for (var i = 0; i < 17; i++)
+          ImageDropEvent(
+            index: i,
+            key: 'content-00$i',
+            fromCurrentMessage: false,
+          ),
+    ],
+    cap: 20,
+    modelId: 'zai/glm-5.3-flash',
+    currentImageCount: prominent ? 25 : 0,
+    registryCount: prominent ? 25 : 37,
+    ridingCount: 20,
+  );
+  return ImageDropUx().observe(report)!;
+}
