+      body: Column(
+        children: [
+          const Spacer(),
+          ImageDropNoticeChip(notice: notice),
+          const SizedBox(height: 24),
+        ],
+      ),
+    ),
+    size: goldenSizePhone,
+    theme: light ? buildFahThemeLight() : buildFahTheme(),
+    locale: const Locale('en'),
