+            index: i,
+            key: 'content-0$i',
+            fromCurrentMessage: false,
+          ),
+      ],
+      cap: 20,
+      modelId: 'zai/glm-5.3-flash',
+      currentImageCount: 0,
+      registryCount: 37,
+      ridingCount: 20,
